+/** Load learner-owned plans and decks that can be assembled into a course. */
+export async function loadCourseAssemblySources(): Promise<CourseAssemblySources> {
+	await getInitPromise();
+	const [metadata, decks] = await Promise.all([
+		sessions.getAllMetadata() as Promise<SessionMetadata[]>,
+		keatingStorage.getDecks(),
+	]);
+	const candidates = metadata
+		.filter((entry) => !entry.hiddenAlternative)
+		.filter((entry) => entry.searchText === undefined || entry.searchText.includes("StudyPlan("))
+		.sort((left, right) => right.lastModified.localeCompare(left.lastModified));
+	const loaded = await Promise.all(candidates.map((entry) => sessions.loadSession(entry.id) as Promise<SessionData | null>));
+	const plans = (await Promise.all(loaded.filter((session): session is SessionData => Boolean(session)).map(studyPlansFromSession))).flat();
+	return {
+		plans,
+		decks: [...decks].sort((left, right) => right.updatedAt - left.updatedAt),
+	};
+}
+
+function safeId(prefix: string, parts: readonly (string | number)[]): string {
+	const slug = parts.join("_")
+		.normalize("NFKD")
+		.replace(/[\u0300-\u036f]/g, "")
+		.replace(/[^A-Za-z0-9_-]+/g, "_")
+		.replace(/^_+|_+$/g, "")
+		.slice(0, Math.max(2, 95 - prefix.length));
+	return `${prefix}_${slug || "item"}`.slice(0, 96);
+}
+
+function remapLesson(lesson: CourseLesson, planIndex: number, moduleIndex: number, lessonIndex: number): CourseLesson {
+	const id = safeId("lesson", [planIndex + 1, moduleIndex + 1, lessonIndex + 1, lesson.title]);
+	return {
+		...lesson,
+		id,
+		materialIds: [],
+		cardIds: [],
+		...(lesson.exercise
+			? { exercise: { ...lesson.exercise, id: safeId("exercise", [planIndex + 1, moduleIndex + 1, lessonIndex + 1]) } }
+			: {}),
+	};
+}
+
+function selectedModules(selection: SelectedStudyPlan, planIndex: number): CourseModule[] {
+	const selected = selection.moduleIds ? new Set(selection.moduleIds) : null;
