+		: selection.source;
+	return courseFromStudyPlan(source).modules.map((module, moduleIndex) => ({
+		...module,
+		id: safeId("module", [planIndex + 1, moduleIndex + 1, module.title]),
+		lessons: module.lessons.map((lesson, lessonIndex) => remapLesson(lesson, planIndex, moduleIndex, lessonIndex)),
+	}));
